"use client";

import * as React from "react";

import {
  type BankAccountResult,
  confirmMatches,
  normalizeBankAccount,
  validateBankAccount,
} from "../../lib/bank-account";
import { cn, controlClasses, Field, useFieldState } from "./field";

export interface BankAccountInputProps
  extends Omit<
    React.ComponentProps<"input">,
    "value" | "defaultValue" | "onChange" | "type"
  > {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: BankAccountResult) => void;
  validateOn?: "blur" | "change";
  /**
   * Render a second "confirm account number" field. On by default: account
   * numbers have no checksum, so re-entry is the only client-side defence
   * against a typo that silently pays a stranger.
   */
  requireConfirmation?: boolean;
  confirmLabel?: string;
  label?: string;
  description?: string;
  containerClassName?: string;
}

export function BankAccountInput({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  requireConfirmation = true,
  confirmLabel = "Confirm account number",
  label,
  description,
  className,
  containerClassName,
  id,
  onBlur,
  ...props
}: BankAccountInputProps) {
  const reactId = React.useId();
  const inputId = id ?? `account-${reactId}`;
  const messageId = `${inputId}-message`;
  const confirmId = `${inputId}-confirm`;
  const confirmMessageId = `${confirmId}-message`;

  const [confirmation, setConfirmation] = React.useState("");
  const [confirmTouched, setConfirmTouched] = React.useState(false);

  const field = useFieldState<BankAccountResult>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate: validateBankAccount,
    transform: (raw) => normalizeBankAccount(raw).slice(0, 18),
    validateOn,
  });

  const mismatch =
    requireConfirmation && confirmTouched && confirmation.length > 0
      ? !confirmMatches(field.value, confirmation)
      : false;

  return (
    <div className={cn("space-y-3", containerClassName)}>
      <Field
        id={inputId}
        messageId={messageId}
        label={label}
        message={field.error ?? description}
        tone={field.error ? "error" : "muted"}
      >
        <input
          {...props}
          id={inputId}
          type="text"
          inputMode="numeric"
          autoComplete="off"
          placeholder={props.placeholder ?? "123456789012"}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error),
              success: field.success,
            }),
            "tracking-[0.14em]",
            className,
          )}
        />
      </Field>

      {requireConfirmation && (
        <Field
          id={confirmId}
          messageId={confirmMessageId}
          label={confirmLabel}
          message={
            mismatch ? "The two account numbers don't match." : undefined
          }
          tone="error"
        >
          <input
            id={confirmId}
            type="text"
            inputMode="numeric"
            // Pasting defeats the point of asking twice.
            onPaste={(event) => event.preventDefault()}
            autoComplete="off"
            placeholder="Re-enter to confirm"
            value={confirmation}
            onChange={(event) =>
              setConfirmation(
                normalizeBankAccount(event.target.value).slice(0, 18),
              )
            }
            onBlur={() => setConfirmTouched(true)}
            aria-invalid={mismatch}
            aria-describedby={confirmMessageId}
            className={cn(
              controlClasses({
                error: mismatch,
                success: confirmation.length > 0 && !mismatch && field.success,
              }),
              "tracking-[0.14em]",
            )}
          />
        </Field>
      )}
    </div>
  );
}

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

/**
 * Indian bank account number validation.
 *
 * There is no national standard and no checksum — length and composition vary
 * by bank (SBI uses 11 digits, HDFC 14, ICICI 12, and cooperative banks do
 * their own thing). So the only honest offline checks are: digits only, and a
 * plausible length.
 *
 * Because a typo here silently sends money to a stranger, the real safeguards
 * are elsewhere: make the user type it twice (`confirmMatches`), and verify
 * with a penny-drop / name-match API before the first transfer.
 */

const MIN_LENGTH = 9;
const MAX_LENGTH = 18;

export type BankAccountErrorCode =
  | "empty"
  | "not_digits"
  | "too_short"
  | "too_long"
  | "all_same_digit";

export interface BankAccountResult {
  valid: boolean;
  normalized: string;
  /** `XXXXXX3210` — safe for display and logs. */
  masked?: string;
  error?: { code: BankAccountErrorCode; message: string };
}

function bad(
  code: BankAccountErrorCode,
  message: string,
  normalized: string,
): BankAccountResult {
  return { valid: false, normalized, error: { code, message } };
}

export function normalizeBankAccount(input: string): string {
  return input.replace(/\D/g, "");
}

/** Mask all but the last four digits. */
export function maskBankAccount(input: string): string {
  const digits = normalizeBankAccount(input);
  if (digits.length < 4) return digits.replace(/\d/g, "X");
  return `${"X".repeat(digits.length - 4)}${digits.slice(-4)}`;
}

export function validateBankAccount(input: string): BankAccountResult {
  const digits = normalizeBankAccount(input);

  if (!input.trim()) return bad("empty", "Enter an account number.", digits);
  if (/[^\d\s-]/.test(input)) {
    return bad("not_digits", "An account number is digits only.", digits);
  }
  if (digits.length < MIN_LENGTH) {
    return bad(
      "too_short",
      `Account numbers are at least ${MIN_LENGTH} digits — ${digits.length} so far.`,
      digits,
    );
  }
  if (digits.length > MAX_LENGTH) {
    return bad(
      "too_long",
      `Account numbers are at most ${MAX_LENGTH} digits.`,
      digits,
    );
  }
  // 000000000 / 111111111 are placeholders, never real accounts.
  if (/^(\d)\1+$/.test(digits)) {
    return bad(
      "all_same_digit",
      "That doesn't look like a real account number.",
      digits,
    );
  }

  return { valid: true, normalized: digits, masked: maskBankAccount(digits) };
}

/** True when a re-typed account number matches the original. */
export function confirmMatches(account: string, confirmation: string): boolean {
  return (
    normalizeBankAccount(account) === normalizeBankAccount(confirmation) &&
    normalizeBankAccount(account).length > 0
  );
}
